/**
 * CHANNEL REGISTRY — where a published article should actually go, and what each
 * destination expects.
 *
 * The engine already had three channels (LinkedIn, an X thread, a newsletter
 * blurb) generated by one LLM call. That is a fraction of the places a piece can
 * legitimately land, and the LLM was doing work that does not need a model: the
 * per-article social copy in `content-studio/<slug>/social.json` is already
 * written, humanised, and fact-checked by the same gates as the article.
 *
 * So this module is deterministic on purpose. Every channel asset is assembled
 * from material that already passed review: the article's title, its short
 * version, its own social.json, and its real published URL. No new claims can
 * appear at distribution time, which is exactly the property you want when the
 * copy is going out under the brand's name.
 *
 * Each channel carries its own rules because the rules are the whole game. A
 * link that is welcome on LinkedIn gets you banned on Reddit; a cross-post
 * without a canonical tag competes with the original in search. Those are
 * encoded as data, not left to whoever is posting that day.
 */

export type ChannelKind = "social" | "community" | "syndication" | "email" | "video";

/** How a destination treats a self-promotional link. Drives what we generate. */
export type SelfPromoPolicy =
  | "welcome" // our own account, our own audience
  | "contextual" // fine when it answers the actual question
  | "restricted" // only with a disclosure, and only if genuinely on topic
  | "forbidden"; // never lead with a link here

export type ChannelSpec = {
  id: string;
  label: string;
  kind: ChannelKind;
  /** Hard character budget for the body, where the platform has one. */
  maxChars?: number;
  /** Does a bare link belong in the post itself? */
  allowsLinks: boolean;
  selfPromo: SelfPromoPolicy;
  /**
   * True when publishing the full article text there would compete with the
   * original in search. Those channels REQUIRE a canonical URL back to us.
   */
  requiresCanonical?: boolean;
  /** Practical guidance shown in the dashboard next to the draft. */
  note: string;
};

