export const CHANNEL_IDS = CHANNELS.map((c) => c.id);
export function getChannel(id: string): ChannelSpec | undefined {
  return CHANNELS.find((c) => c.id === id);
}

/* -------------------------------------------------------------------------- *
 * Source material
 * -------------------------------------------------------------------------- */

/** Everything a channel builder is allowed to draw from. All pre-reviewed. */
export type ArticleSource = {
  slug: string;
  title: string;
  url: string;
  /** The article's own short-version box or meta description. */
  summary: string;
  /** Sentences from the short version, used to build threads and bullets. */
  points: string[];
  tags: string[];
  /** Reused verbatim when present: already written and already checked. */
  social?: {
    x?: string;
    linkedin?: string;
    thread?: string[];
  } | null;
};

export type ChannelAsset = {
  channel: string;
  /** What a human copies out. */
  body: string;
  /** Set for channels that have one (newsletter subject, HN title). */
  subject?: string;
  /** Threads keep their parts separate so each can be posted in order. */
  parts?: string[];
  hashtags?: string[];
  canonicalUrl?: string;
  /** Rules the poster needs to see at the moment of posting. */
  guidance: string;
};

const clip = (s: string, n: number): string => {
  const t = s.replace(/\s+/g, " ").trim();
  if (t.length <= n) return t;
  return `${t.slice(0, n - 1).replace(/\s+\S*$/, "")}\u2026`;
};

const sentences = (s: string): string[] =>
  (s || "")
    .split(/(?<=[.!?])\s+/)
    .map((x) => x.trim())
    .filter(Boolean);

const tagLine = (tags: string[], max = 5): string =>
  tags
    .slice(0, max)
    .map((t) => (t.startsWith("#") ? t : `#${t}`))
    .join(" ");

/* -------------------------------------------------------------------------- *
 * Builders. One per channel, deterministic, no model call.
 * -------------------------------------------------------------------------- */

function buildLinkedIn(a: ArticleSource): ChannelAsset {
  const body =
    a.social?.linkedin?.trim() ||
    [
      a.title,
      "",
      clip(a.points.slice(0, 3).join(" ") || a.summary, 700),
      "",
      `Full guide: ${a.url}`,
      "",
      tagLine(a.tags),
    ].join("\n");
  return {
    channel: "linkedin",
    body: clip(body, 3000),
    hashtags: a.tags.slice(0, 5),
    guidance: getChannel("linkedin")!.note,
  };
}

function buildXThread(a: ArticleSource): ChannelAsset {
  const parts =
    a.social?.thread?.length
      ? a.social.thread
      : [
          clip(a.title, 260),
          ...a.points.slice(0, 4).map((p) => clip(p, 260)),
          clip(`Full walkthrough:\n${a.url}\n${tagLine(a.tags, 3)}`, 260),
        ];
  return {
    channel: "x_thread",
    body: parts.join("\n\n---\n\n"),
    parts,
    guidance: getChannel("x_thread")!.note,
  };
}

function buildNewsletter(a: ArticleSource): ChannelAsset {
  const lead = a.points[0] ?? a.summary;
  return {
    channel: "newsletter",
    subject: clip(a.title, 78),
    body: [
      clip(lead, 240),
      "",
      clip(a.points.slice(1, 3).join(" ") || a.summary, 420),
      "",
      `Read it here: ${a.url}`,
    ].join("\n"),
    guidance: getChannel("newsletter")!.note,
  };
}

function buildFacebook(a: ArticleSource): ChannelAsset {
  return {
    channel: "facebook",
    body: clip([a.title, "", clip(a.summary, 500), "", a.url].join("\n"), 2000),
    guidance: getChannel("facebook")!.note,
  };
}

function buildInstagram(a: ArticleSource): ChannelAsset {
  return {
    channel: "instagram",
    body: clip(
      [
        a.title,
        "",
        clip(a.points.slice(0, 2).join(" ") || a.summary, 600),
        "",
        "Full guide linked in bio.",
        "",
        tagLine(a.tags, 8),
      ].join("\n"),
      2200,
    ),
    hashtags: a.tags.slice(0, 8),
    guidance: getChannel("instagram")!.note,
  };
}

function buildYouTubeDescription(a: ArticleSource): ChannelAsset {
  return {
    channel: "youtube_description",
    body: [
      clip(a.summary, 300),
      "",
      `Written version: ${a.url}`,
      "",
      "In this video:",
      ...a.points.slice(0, 5).map((p) => `- ${clip(p, 110)}`),
      "",
      tagLine(a.tags, 5),
    ].join("\n"),
    guidance: getChannel("youtube_description")!.note,
  };
}

function buildReddit(a: ArticleSource): ChannelAsset {
  // Deliberately shaped as an answer, not a promo. The link is optional and
  // disclosed, because that is the only version of this that is welcome.
  return {
    channel: "reddit",
    body: [
      clip(a.points.slice(0, 3).join(" ") || a.summary, 900),
      "",
      "The short version of what usually fixes it:",
      ...a.points.slice(0, 4).map((p) => `- ${clip(p, 160)}`),
      "",
      `(I work at Kloudbean and we wrote this up in more depth here: ${a.url} — happy to answer follow-ups in the thread either way.)`,
    ].join("\n"),
    guidance: getChannel("reddit")!.note,
  };
}

function buildHackerNews(a: ArticleSource): ChannelAsset {
  return {
    channel: "hacker_news",
    subject: clip(a.title.replace(/^(how to|why)\s+/i, (m) => m), 80),
    body: [
      `Submission URL: ${a.url}`,
      "",
      "If you comment, lead with the technical finding, not the product:",
      ...a.points.slice(0, 3).map((p) => `- ${clip(p, 160)}`),
    ].join("\n"),
    guidance: getChannel("hacker_news")!.note,
  };
}

function buildSyndication(a: ArticleSource, channel: string): ChannelAsset {
  return {
    channel,
    subject: a.title,
    body: [
      `Cross-post the full article, then set the canonical URL to:`,
      a.url,
      "",
      "Suggested intro paragraph:",
      clip(a.summary, 400),
      "",
      `Tags: ${a.tags.map((t) => t.replace(/^#/, "")).slice(0, 4).join(", ")}`,
    ].join("\n"),
    canonicalUrl: a.url,
    guidance: getChannel(channel)!.note,
  };
}

function buildCommunityChat(a: ArticleSource): ChannelAsset {
  return {
    channel: "community_chat",
    body: clip(
      [`${clip(a.points[0] ?? a.summary, 300)}`, "", `Wrote it up here: ${a.url}`].join("\n"),
      1200,
    ),
    guidance: getChannel("community_chat")!.note,
  };
}

/** Build the asset for one channel. Returns null for an unknown channel id. */
export function buildChannelAsset(channel: string, a: ArticleSource): ChannelAsset | null {
  switch (channel) {
    case "linkedin":
      return buildLinkedIn(a);
    case "x_thread":
      return buildXThread(a);
    case "newsletter":
      return buildNewsletter(a);
    case "facebook":
      return buildFacebook(a);
    case "instagram":
      return buildInstagram(a);
    case "youtube_description":
      return buildYouTubeDescription(a);
    case "reddit":
      return buildReddit(a);
    case "hacker_news":
      return buildHackerNews(a);
    case "dev_to":
    case "hashnode":
    case "medium":
      return buildSyndication(a, channel);
    case "community_chat":
      return buildCommunityChat(a);
    default:
      return null;
  }
}

/** Build every channel asset for an article. */
export function buildAllChannelAssets(a: ArticleSource, only?: string[]): ChannelAsset[] {
  const ids = only?.length ? only : CHANNEL_IDS;
  return ids
    .map((id) => buildChannelAsset(id, a))
    .filter((x): x is ChannelAsset => x !== null);
}

/** Split a summary into the point list the builders use. */
export function pointsFromSummary(summary: string, fallback: string[] = []): string[] {
  const s = sentences(summary);
  return s.length ? s : fallback;
}
